insert into public.business_divisions (id, slug, name, short_name, sub_brand, tagline, description, kind, accent_color, hero_image, banner_image, logo_url, sort_order, is_active) values ('00000001-0000-4000-8000-000000000001', 'fashion', 'AUREYA by RAVANTRA', 'Fashion', 'AUREYA', 'Elegance in Every Thread.', 'AUREYA is RAVANTRA''s women''s fashion house — Indian heritage craft meets contemporary silhouettes, from handwoven sarees to statement evening wear and everyday essentials.', 'products', '#6B1E2E', '/images/fashion/tiger-crest-hoodie.webp', '/images/fashion/fashion-banner.webp', null, 1, true) on conflict (id) do nothing;
