insert into public.products (id, division_id, category_id, slug, name, sku, short_description, description, price, sale_price, ingredients, highlights, tags, is_featured, is_new, is_active, created_at) values ('00000003-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000001', '00000002-0000-4000-8000-000000000004', 'lavender-tissue-silk-saree', 'Lavender Tissue Silk Saree', 'RV-FA-001', 'Shimmering lilac tissue silk with a gold-woven border.', 'Light-catching tissue silk in soft lavender, woven with a fine gold border and a pallu that falls in liquid pleats. Paired with a hand-embellished sweetheart blouse worked in zardozi, sequins and cut beads — made for receptions, sangeets and festive evenings.', 24900, 21900, null, array['Pure tissue silk','Hand-embellished zardozi blouse','Gold-woven border & pallu','Blouse stitched to measure']::text[], array['saree','festive','bridal','new-season']::text[], true, true, true, now() - interval '4 days 0 hours') on conflict (id) do nothing;
