insert into public.reviews (id, product_id, author_name, rating, title, body, is_demo, created_at) values ('00000008-0000-4000-8000-000000000001', '00000003-0000-4000-8000-000000000001', 'Priya S.', 5, 'An heirloom piece', 'The zardozi on the blouse is exquisite and the tissue silk drapes so well. Felt very special.', true, now() - interval '6 days 0 hours') on conflict (id) do nothing;
insert into public.reviews (id, product_id, author_name, rating, title, body, is_demo, created_at) values ('00000008-0000-4000-8000-000000000002', '00000003-0000-4000-8000-00000000000a', 'Aditi R.', 5, 'My skin has never looked better', 'Two weeks in and my skin is visibly brighter. Absorbs fast and doesn''t break me out.', true, now() - interval '15 days 0 hours') on conflict (id) do nothing;
